// Generates src/generated/schema.ts from openapi.json with openapi-typescript.
// Run through `make api-client` (which exports openapi.json first), never by
// hand-editing the output. Reads and writes only files in this package.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import openapiTS, { astToString } from 'openapi-typescript';

const root = new URL('../', import.meta.url);
const input = new URL('openapi.json', root);
const output = new URL('src/generated/schema.ts', root);

const HEADER = `/**
 * GENERATED FILE - DO NOT EDIT BY HAND.
 *
 * Generated by \`make api-client\` from packages/api-client/openapi.json
 * (openapi-typescript). Change the API, then run \`make api-client\` and
 * commit the result; CI (\`make check-api-client\`) fails on any drift.
 */

`;

const document = JSON.parse(await readFile(input, 'utf8'));
const ast = await openapiTS(document);
await mkdir(new URL('./', output), { recursive: true });
await writeFile(output, HEADER + astToString(ast), 'utf8');
